async function runTool(call) {
  try {
    const output = await tools[call.name](call.input);
    return { type: 'tool_result', tool_use_id: call.id,
      content: JSON.stringify(output) };
  } catch (error) {
    return { type: 'tool_result', tool_use_id: call.id,
      is_error: true, content: error.message };
  }
}

